 {title:'自由曲線',sub:'曲線也可以離開平面',detail:'曲線可以存在於三維空間，不必全部位於同一個平面。',make:()=>{const p=[v(-1.4,-.8,.25),v(-1,1.6,2.6),v(.9,-1.8,2.8),v(1.4,.8,.3)];catalogLine(new THREE.CubicBezierCurve3(...p).getPoints(100),0x194d3a);catalogLine(p,0xb09063);p.forEach(x=>dot(x,0xaa7a3e,null,.06));}}
