const catalogDescriptions=[
'同樣是點，可以用來標記位置、排列輪廓，或成為曲線與曲面的控制結構。先看這四種情境，再比較點物件與控制點的角色。',
'直線、圓、多段線組成的輪廓，以及在空間中彎曲的自由曲線，都屬於曲線。曲線不一定彎，也不一定全部位於同一個平面。',
'平面、波浪面、圓柱側面與球面，都可以由單張曲面描述。它們的外形與封閉狀態不同；表面的等參數線則幫助我們閱讀形狀。',
'把不同的平面輪廓，沿固定方向延伸，就能得到不同的等截面形狀。比較圓形、L 形與星形輪廓，以及加上封口和不封口的差別。',
'多張曲面沿邊緣組合，可以變成一個多重曲面。從圓柱的三張面，到帶孔的複合外形，都可以透過拆開觀察來理解組成。',
'球體、環狀體與帶孔塊體的外觀不同，但都能有完整封閉的邊界。有穿孔不代表開放；缺少封口才是這組對照要辨認的差別。',
'網格透過多邊形面描述外形；SubD 使用控制結構與細分規則描述平滑外形。此處僅作類型辨識，不安排編輯練習。'
];
const catalogTasks=[
 '先比較獨立點、點的排列與控制點。點選圖上的標籤，可以放大並讀取它的用途。',
 '比較直線、多重曲線、封閉曲線與空間曲線：它們看起來不同，但都屬於曲線。',
 '一起比較平面、波浪面、圓柱側面與球面。點選標籤，觀察它們各自的邊界與形狀。',
 '比較圓形、L 形、星形擠出。輪廓各不相同，但都沿固定方向維持相同的截面。',
 '比較組合、分解與開放狀態。留意圓孔的孔壁：有洞，不一定代表沒有封閉。',
 '比較球體、環狀體、帶孔塊體與開口圓柱。哪個「有洞」，卻仍然可以是封閉實體？',
 '只先認識這兩種物件的外觀與控制結構，不進入編輯練習。'
];
function setLessonCopy(){document.querySelector('.command-location')?.remove();document.querySelector('.try .eyebrow').textContent=active===7?'怎麼找到這個圖示':'動手觀察';if(active===7){document.body.classList.add('commands-mode');return;}document.body.classList.remove('commands-mode');document.body.classList.toggle('catalog-mode',galleryMode);$('gallery-view').setAttribute('aria-pressed',String(galleryMode));$('experiment-view').setAttribute('aria-pressed',String(!galleryMode));$('description').textContent=galleryMode?catalogDescriptions[active]:chapters[active].description;$('task').textContent=galleryMode?catalogTasks[active]:chapters[active].task;$('headline').textContent=galleryMode?['位置，可以有不同用途。','不同的線，都是曲線。','曲面，不只有一種樣子。','不同輪廓，同樣的延伸邏輯。','拆開來，才看懂組成。','有洞，不一定沒有封閉。','先認得，再決定何時使用。'][active]:chapters[active].headline;}
function catalogCamera(){group.updateMatrixWorld(true);const bounds=new THREE.Box3().setFromObject(group),center=bounds.getCenter(v(0,0,0));const dir=v(.35,-.62,.7).normalize(),right=v(0,0,1).cross(dir).normalize(),up=dir.clone().cross(right).normalize();const aspect=viewport.clientWidth/viewport.clientHeight,tanV=Math.tan(camera.fov*Math.PI/360);let distance=4;group.traverse(o=>{const positions=o.geometry?.getAttribute('position');if(!positions)return;const stride=Math.max(1,Math.floor(positions.count/1200));for(let i=0;i<positions.count;i+=stride){const q=v(positions.getX(i),positions.getY(i),positions.getZ(i)).applyMatrix4(o.matrixWorld).sub(center);distance=Math.max(distance,q.dot(dir)+Math.max(Math.abs(q.dot(right))/(tanV*aspect),Math.abs(q.dot(up))/tanV));}});orbit.target.copy(center);camera.position.copy(center).addScaledVector(dir,distance*1.14);orbit.update();}
function drawCatalog(){const samples=catalog[active];const chosen=focusedSample===null?samples:[samples[focusedSample]];const count=chosen.length;const root=group;chosen.forEach((sample,j)=>{const i=focusedSample===null?j:focusedSample;const g=new THREE.Group();group=g;sample.make();group=root;root.add(g);const x=count===1?0:(j%2?2.65:-2.65),y=count<=2?0:(j<2?2.4:-2.4);g.position.set(x,y,.08);if(count===1)g.scale.setScalar(1.35);g.updateMatrixWorld(true);const label=document.createElement('button');label.className='object-label';label.innerHTML=`${sample.title}<small>${sample.sub}</small>`;label.onclick=()=>focusCatalog(i);$('object-labels').append(label);catalogLabels.push({el:label,object:g,point:v(0,-1.8,-.14)});});$('model-tag').textContent=focusedSample===null?'OBJECT ATLAS / COMPARE THE TYPES':'FOCUS / '+samples[focusedSample].title;$('status').textContent=focusedSample===null?catalogTasks[active]:samples[focusedSample].detail;}
function positionCatalogLabels(){for(const item of catalogLabels){const p=item.object.localToWorld(item.point.clone()).project(camera);if(item.spatial){item.el.style.left=`${(p.x+1)*viewport.clientWidth/2}px`;item.el.style.top=`${(1-p.y)*viewport.clientHeight/2}px`;item.el.hidden=p.z>1||p.z< -1;continue;}item.el.style.left=`${THREE.MathUtils.clamp((p.x+1)*viewport.clientWidth/2,78,viewport.clientWidth-78)}px`;item.el.style.top=`${THREE.MathUtils.clamp((1-p.y)*viewport.clientHeight/2,60,viewport.clientHeight-77)}px`;item.el.hidden=p.z>1||p.z< -1;}}
function focusCatalog(i){focusedSample=i;controls();draw();catalogCamera();}
function catalogControls(){const p=document.createElement('p');p.className='gallery-help';p.innerHTML=focusedSample===null?'<strong>一組物件，一起比較。</strong> 點選標籤或下方名稱，放大觀察。':`<strong>${catalog[active][focusedSample].title}</strong> · ${catalog[active][focusedSample].sub}`;$('controls').append(p);const wrap=document.createElement('div');wrap.className='switches';const overview=document.createElement('button');overview.textContent='全部比較';overview.classList.toggle('selected',focusedSample===null);overview.setAttribute('aria-pressed',String(focusedSample===null));overview.onclick=()=>{focusedSample=null;controls();draw();catalogCamera();};wrap.append(overview);catalog[active].forEach((s,i)=>{const b=document.createElement('button');b.textContent=s.title;b.classList.toggle('selected',focusedSample===i);b.setAttribute('aria-pressed',String(focusedSample===i));b.onclick=()=>focusCatalog(i);wrap.append(b);});$('controls').append(wrap);}
$('gallery-view').onclick=()=>{galleryMode=true;focusedSample=null;setLessonCopy();setSpatialCopy();controls();draw();catalogCamera();};
$('experiment-view').onclick=()=>{galleryMode=false;setLessonCopy();setSpatialCopy();controls();draw();resetCamera();};

const axisColors={x:0xff7878,y:0x9fe489,z:0x7fb9ff};
const axisVectors={x:v(1,0,0),y:v(0,1,0),z:v(0,0,1)};
const curvePresets={space:[[-2,-1,.3],[-1,1.7,3],[1,-1.7,2.5],[2,1,.6]],flat:[[-2,-1,.3],[-1,1.7,.3],[1,-1.7,.3],[2,1,.3]]};
let axisHandles=[],historyBack=[],historyForward=[];
function initialSurface(kind='wave'){return Array.from({length:16},(_,k)=>{const i=Math.floor(k/4),j=k%4;let z=.8+[0,2,-.7,.4][i]+[0,-.5,.7,.2][j];if(kind==='saddle')z=1.4+(i-1.5)*(j-1.5)*.65;if(kind==='flat')z=1.1;return [-2+4*i/3,-1.5+j,z];});}
function spatialDefaults(){return {pointMode:'object',p:[.5,-.3,1.7],cp:curvePresets.space.map(p=>[...p]),curve:'free',curvePreset:'space',net:true,surfCP:initialSurface(),selected:1,surfaceSelected:5,dragPlane:'view',height:3,caps:true,explode:.4,top:true,width:4,depth:3,profile:'circle',dx:1,dy:.4,face:4,faceOffsets:Array.from({length:6},()=>[0,0,0]),commandCategory:'all',selectedCommand:'Point'};}
function recordEdit(){historyBack.push(JSON.stringify(state));if(historyBack.length>50)historyBack.shift();historyForward=[];}
function undoEdit(){if(!historyBack.length)return;historyForward.push(JSON.stringify(state));state=JSON.parse(historyBack.pop());controls();draw();}
function redoEdit(){if(!historyForward.length)return;historyBack.push(JSON.stringify(state));state=JSON.parse(historyForward.pop());controls();draw();}
function dashed(points,color=0x557872){const g=new THREE.BufferGeometry().setFromPoints(points);const o=new THREE.Line(g,new THREE.LineDashedMaterial({color,dashSize:.1,gapSize:.08,transparent:true,opacity:.65}));o.computeLineDistances();group.add(o);return o;}
function spatialLabel(text,p,className='coordinate-label'){const el=document.createElement('span');el.className=className;el.textContent=text;$('object-labels').append(el);catalogLabels.push({el,object:group,point:p.clone(),spatial:true});}
function editTarget(){if(active===0&&state.pointMode==='object')return v(...state.p);if(active===0||active===1)return v(...state.cp[state.selected]);if(active===2)return v(...state.surfCP[state.surfaceSelected]);if(active===3)return v(state.dx,state.dy,state.height);if(active===4)return faceCenter(state.face).add(v(...state.faceOffsets[state.face]));return null;}
function setEditTarget(p){p.x=THREE.MathUtils.clamp(p.x,-4,4);p.y=THREE.MathUtils.clamp(p.y,-4,4);p.z=THREE.MathUtils.clamp(p.z,-1,5);if(active===0&&state.pointMode==='object')state.p=p.toArray();else if(active===0||active===1){state.cp[state.selected]=p.toArray();state.curvePreset='custom';}else if(active===2)state.surfCP[state.surfaceSelected]=p.toArray();else if(active===3){state.dx=p.x;state.dy=p.y;state.height=THREE.MathUtils.clamp(p.z,.3,5);}else if(active===4)state.faceOffsets[state.face]=p.clone().sub(faceCenter(state.face)).toArray();}
function worldGizmo(p){for(const [axis,dir]of Object.entries(axisVectors)){const arrow=new THREE.ArrowHelper(dir,p,1.05,axisColors[axis],.23,.12);arrow.line.material.depthTest=false;arrow.cone.material.depthTest=false;arrow.renderOrder=90;for(const child of [arrow.line,arrow.cone]){child.userData={axis};child.renderOrder=90;axisHandles.push(child);}group.add(arrow);spatialLabel(axis.toUpperCase(),p.clone().addScaledVector(dir,1.25),'axis-caption axis-'+axis);}}
function projectionGuide(points){for(const p of points)dashed([v(p.x,p.y,-.09),p],0x3e6866);dashed(points.map(p=>v(p.x,p.y,-.085)),0x4f827c);}
function drawSpatialCurve(){const cps=state.cp.map(p=>v(...p));const curve=new THREE.CubicBezierCurve3(...cps);line(curve.getPoints(90),0xc1fce1);dashed(cps,0xd19760);cps.forEach((p,i)=>{dot(p,i===state.selected?0xffda9a:0xe1ad78,i,i===state.selected?.13:.095);spatialLabel(String(i+1),p.clone().add(v(0,0,.19)),'point-caption'+(i===state.selected?' chosen':''));});projectionGuide(curve.getPoints(32));worldGizmo(cps[state.selected]);}
function surfacePoint(u,w){const b=t=>[(1-t)**3,3*t*(1-t)**2,3*t*t*(1-t),t**3],bu=b(u),bv=b(w);const p=v(0,0,0);for(let i=0;i<4;i++)for(let j=0;j<4;j++)p.addScaledVector(v(...state.surfCP[i*4+j]),bu[i]*bv[j]);return p;}
function drawSpatialSurface(){const n=28,verts=[],idx=[];for(let i=0;i<=n;i++)for(let j=0;j<=n;j++)verts.push(...surfacePoint(i/n,j/n).toArray());for(let i=0;i<n;i++)for(let j=0;j<n;j++){const a=i*(n+1)+j,b=a+n+1;idx.push(a,b,b+1,a,b+1,a+1);}const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));geometry.setIndex(idx);geometry.computeVertexNormals();group.add(new THREE.Mesh(geometry,new THREE.MeshStandardMaterial({color:0x88c6b4,side:THREE.DoubleSide,roughness:.3,metalness:.2})));for(let k=0;k<=6;k++){line(Array.from({length:51},(_,j)=>surfacePoint(k/6,j/50)),k===0||k===6?0xc8fae1:0x426f66);line(Array.from({length:51},(_,j)=>surfacePoint(j/50,k/6)),k===0||k===6?0xc8fae1:0x426f66);}if(state.net){for(let i=0;i<4;i++){dashed(Array.from({length:4},(_,j)=>v(...state.surfCP[i*4+j])),0xa78c68);dashed(Array.from({length:4},(_,j)=>v(...state.surfCP[j*4+i])),0xa78c68);}state.surfCP.forEach((p,i)=>dot(v(...p),i===state.surfaceSelected?0xffdc9e:0xdba974,i,i===state.surfaceSelected?.12:.065));const p=v(...state.surfCP[state.surfaceSelected]);projectionGuide([p]);worldGizmo(p);spatialLabel(`控制點 ${Math.floor(state.surfaceSelected/4)+1}, ${state.surfaceSelected%4+1}`,p.clone().add(v(0,0,.28)),'coordinate-label');}}
function profileShape(){const s=new THREE.Shape();if(state.profile==='circle')s.absarc(0,0,1.5,0,Math.PI*2,false);else if(state.profile==='star'){for(let i=0;i<10;i++){const a=i*Math.PI/5,r=i%2?.8:1.7;if(i===0)s.moveTo(r*Math.cos(a),r*Math.sin(a));else s.lineTo(r*Math.cos(a),r*Math.sin(a));}s.closePath();}else{s.moveTo(-1.6,-1.3);s.lineTo(1.6,-1.3);s.lineTo(1.6,-.3);s.lineTo(-.4,-.3);s.lineTo(-.4,1.3);s.lineTo(-1.6,1.3);s.closePath();}return s;}
function drawSpatialExtrusion(){const shape=profileShape(),points=shape.getPoints(80);if(points[0].distanceTo(points.at(-1))>.0001)points.push(points[0].clone());const base=points.map(p=>v(p.x,p.y,0)),top=points.map(p=>v(p.x+state.dx,p.y+state.dy,state.height));const vertices=[],indices=[];for(let i=0;i<base.length-1;i++){const k=vertices.length/3;vertices.push(...base[i].toArray(),...base[i+1].toArray(),...top[i+1].toArray(),...top[i].toArray());indices.push(k,k+1,k+2,k,k+2,k+3);}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));g.setIndex(indices);g.computeVertexNormals();group.add(new THREE.Mesh(g,new THREE.MeshStandardMaterial({color:0x87c9b2,side:THREE.DoubleSide,roughness:.35,metalness:.18})));line(base,0xf2c38a);line(top,0xbcefd6);for(let i=0;i<base.length-1;i+=Math.max(1,Math.floor((base.length-1)/8)))line([base[i],top[i]],0x57917d);if(state.caps){const bottom=new THREE.Mesh(new THREE.ShapeGeometry(shape,64),new THREE.MeshStandardMaterial({color:0x7fb4a0,side:THREE.DoubleSide,roughness:.4}));group.add(bottom);const cap=bottom.clone();cap.geometry=bottom.geometry.clone();cap.material=bottom.material.clone();cap.position.set(state.dx,state.dy,state.height);group.add(cap);}const end=v(state.dx,state.dy,state.height);dashed([v(0,0,0),end],0xf6b46f);dot(end,0xffdda3,'extrusion',.11);worldGizmo(end);spatialLabel('擠出方向端點',end.clone().add(v(0,0,.25)));projectionGuide([end]);}
function faceCorners(){const a=state.width/2,b=state.depth/2,h=state.height;return [[v(-a,-b,0),v(a,-b,0),v(a,-b,h),v(-a,-b,h)],[v(a,-b,0),v(a,b,0),v(a,b,h),v(a,-b,h)],[v(a,b,0),v(-a,b,0),v(-a,b,h),v(a,b,h)],[v(-a,b,0),v(-a,-b,0),v(-a,-b,h),v(-a,b,h)],[v(-a,-b,h),v(a,-b,h),v(a,b,h),v(-a,b,h)],[v(-a,b,0),v(a,b,0),v(a,-b,0),v(-a,-b,0)]];}
function faceCenter(i){return faceCorners()[i].reduce((p,q)=>p.add(q),v(0,0,0)).multiplyScalar(.25);}
function drawSpatialBox(exploded=false){const normals=[v(0,-1,0),v(1,0,0),v(0,1,0),v(-1,0,0),v(0,0,1),v(0,0,-1)];faceCorners().forEach((corners,i)=>{if(i===4&&!state.top)return;const offset=exploded?v(...state.faceOffsets[i]):v(0,0,0);if(exploded)offset.addScaledVector(normals[i],state.explode);const points=corners.map(p=>p.add(offset));const m=sheet(points,exploded&&i===state.face?0xc2dfb5:[0x79bca6,0x74aeb0,0x669582,0x74a6a0,0xb6dac2,0x79a79b][i]);if(exploded){m.userData.face=i;facePickTargets.push(m);dashed([faceCenter(i),faceCenter(i).add(offset)],0x587468);}});if(exploded){const p=faceCenter(state.face).add(v(...state.faceOffsets[state.face])).addScaledVector(normals[state.face],state.explode);worldGizmo(p);}if(!state.top)line(faceCorners()[4].concat([faceCorners()[4][0]]),0xffbc87);}
let facePickTargets=[];
function drawSpatial(){axisHandles=[];facePickTargets=[];let status='',tag='';if(active===0){if(state.pointMode==='object'){const p=v(...state.p);dot(p,0xf6d69a,0,.13);projectionGuide([p]);worldGizmo(p);spatialLabel('點物件',p.clone().add(v(0,0,.3)));status=`X ${p.x.toFixed(1)} ／ Y ${p.y.toFixed(1)} ／ Z ${p.z.toFixed(1)} · 拖曳三色箭頭，分別沿三軸移動。`;tag='POINT / THREE AXES';}else{drawSpatialCurve();status='控制點可沿三個方向移動；橘色是控制結構，地面虛線是曲線的投影。';tag='CONTROL POINT / SPACE';}}
if(active===1){if(state.curve==='free'){drawSpatialCurve();status=`選取控制點 ${state.selected+1} · X ${editTarget().x.toFixed(1)} / Y ${editTarget().y.toFixed(1)} / Z ${editTarget().z.toFixed(1)} · 每個點都可以離開原本的平面。`;tag='SPATIAL CURVE / EDIT CONTROL POINTS';}else{const pts=state.curve==='circle'?Array.from({length:101},(_,i)=>v(1.8*Math.cos(i*Math.PI/50),1.8*Math.sin(i*Math.PI/50),.5)):rect(.5);line(pts);status='這是平面封閉曲線。切換「自由曲線」，逐點編輯空間中的形狀。';tag='PLANAR / CLOSED CURVE';}}
if(active===2){drawSpatialSurface();status=state.net?`16 個控制點可各自移動 · 已選 ${Math.floor(state.surfaceSelected/4)+1},${state.surfaceSelected%4+1} · 地面虛線表示所選點的高度。`:'控制網已隱藏 · 曲面形狀保留，顯示的細線是等參數線。';tag='SURFACE / 16 INDEPENDENT CONTROL POINTS';}
if(active===3){drawSpatialExtrusion();const len=Math.hypot(state.dx,state.dy,state.height);status=`方向向量 (${state.dx.toFixed(1)}, ${state.dy.toFixed(1)}, ${state.height.toFixed(1)}) · 延伸距離 ${len.toFixed(2)} · ${state.caps?'封口':'不封口'}${Math.abs(state.dx)+Math.abs(state.dy)>.01?' · 斜向擠出在 Rhino 中會建立多重曲面':''}`;tag='EXTRUDE / CHANGE THE DIRECTION';}
if(active===4){drawSpatialBox(true);const moved=state.faceOffsets.some(p=>p.some(x=>Math.abs(x)>.001));const apart=state.explode>.001||moved;status=apart?'展示分離的各張面：可點選曲面，再拖曳三軸箭頭。各面分離時，不是相接的多重曲面。':`${state.top?'六張面完整相接，可形成封閉多重曲面':'五張面相接，頂部開放'}`;tag='SURFACE ASSEMBLY / MOVE EACH FACE';}
if(active===5){drawSpatialBox();status=state.top?`封閉實體 · ${state.width.toFixed(1)} × ${state.depth.toFixed(1)} × ${state.height.toFixed(1)} = ${(state.width*state.depth*state.height).toFixed(2)} 立方示意單位`:'頂部開放 · 不是封閉實體，不能當作封閉實體計算體積。';tag=state.top?'SOLID / EDIT THREE DIMENSIONS':'OPEN BOUNDARY';} $('status').textContent=status;$('model-tag').textContent=tag;updateSpatialReadouts();}
function spatialButton(text,action,selected=false){const b=document.createElement('button');b.textContent=text;b.classList.toggle('selected',selected);b.onclick=action;return b;}
function spatialRange(parent,label,min,max,get,set,axis){const wrap=document.createElement('div');wrap.className='spatial-range '+(axis?'axis-'+axis:'');const lab=document.createElement('label');const id='spatial-'+label;lab.htmlFor=id;const out=document.createElement('output');out.dataset.readout=label;lab.append(document.createTextNode(label),out);const input=document.createElement('input');Object.assign(input,{id,type:'range',min,max,step:.05,value:get()});input.dataset.coordinate=label;input.onpointerdown=recordEdit;input.onkeydown=e=>{if(e.key.startsWith('Arrow')||['Home','End','PageUp','PageDown'].includes(e.key))recordEdit();};input.oninput=()=>{set(Number(input.value));draw();};input.onchange=()=>refreshHistoryButtons();input._get=get;wrap.append(lab,input);parent.append(wrap);out.value=Number(get()).toFixed(2);}
function refreshHistoryButtons(){const a=$('undo-edit'),b=$('redo-edit');if(a)a.disabled=!historyBack.length;if(b)b.disabled=!historyForward.length;}
function updateSpatialReadouts(){for(const input of document.querySelectorAll('input[data-coordinate]')){if(!input._get)continue;const value=input._get();if(document.activeElement!==input)input.value=value;const out=document.querySelector(`output[data-readout="${input.dataset.coordinate}"]`);if(out)out.value=Number(value).toFixed(2);}refreshHistoryButtons();}
function spatialControls(){const root=$('controls');const top=document.createElement('div');top.className='edit-toolbar';const title=document.createElement('span');title.textContent='自由編輯 · 拖曳箭頭或調整座標';const undo=spatialButton('↶ 復原',undoEdit);undo.id='undo-edit';const redo=spatialButton('↷ 重做',redoEdit);redo.id='redo-edit';top.append(title,undo,redo);root.append(top);
if(active===0)buttons([['object','點物件'],['control','曲線控制點']],'pointMode');if(active===1)buttons([['free','自由曲線'],['rectangle','矩形'],['circle','圓']],'curve');
if((active===0&&state.pointMode==='control')||(active===1&&state.curve==='free')){const row=document.createElement('div');row.className='switches';for(const [key,label]of [['space','空間曲線'],['flat','平面曲線']])row.append(spatialButton(label,()=>{recordEdit();state.cp=curvePresets[key].map(p=>[...p]);state.curvePreset=key;controls();draw();},state.curvePreset===key));root.append(row);const select=document.createElement('div');select.className='switches point-select';for(let i=0;i<4;i++)select.append(spatialButton('控制點 '+(i+1),()=>{state.selected=i;controls();draw();},state.selected===i));root.append(select);}
if(active===2){const row=document.createElement('div');row.className='switches';for(const [kind,label]of [['wave','波浪面'],['saddle','馬鞍面'],['flat','平面']])row.append(spatialButton(label,()=>{recordEdit();state.surfCP=initialSurface(kind);controls();draw();}));row.append(spatialButton(state.net?'隱藏控制網':'顯示控制網',()=>{state.net=!state.net;controls();draw();}));root.append(row);if(state.net){const nav=document.createElement('div');nav.className='point-selector';nav.append(spatialButton('← 前一點',()=>{state.surfaceSelected=(state.surfaceSelected+15)%16;controls();draw();}),document.createTextNode(`控制點 ${Math.floor(state.surfaceSelected/4)+1}, ${state.surfaceSelected%4+1} ／ 4 × 4`),spatialButton('後一點 →',()=>{state.surfaceSelected=(state.surfaceSelected+1)%16;controls();draw();}));root.append(nav);}}
if(active===3){buttons([['circle','圓形'],['L','L 形'],['star','星形']],'profile');buttons([[true,'上下封口'],[false,'不封口']],'caps');}
if(active===4){const row=document.createElement('div');row.className='switches';['前面','右面','後面','左面','頂面','底面'].forEach((name,i)=>{if(i===4&&!state.top)return;row.append(spatialButton(name,()=>{state.face=i;controls();draw();},state.face===i));});root.append(row);const r=document.createElement('div');r.className='dimension-grid';spatialRange(r,'全部分解',0,1.5,()=>state.explode,x=>state.explode=x);root.append(r);const join=spatialButton('各面回到組合位置',()=>{recordEdit();state.explode=0;state.faceOffsets=Array.from({length:6},()=>[0,0,0]);controls();draw();});join.className='assemble-button';root.append(join);}
if(active===5)buttons([[true,'封閉頂面'],[false,'打開頂面']],'top');
const hasCoordinates=active===0||(active===1&&state.curve==='free')||(active===2&&state.net)||active===3||active===4;if(hasCoordinates){const grid=document.createElement('div');grid.className='dimension-grid';for(const [axis,index]of [['x',0],['y',1],['z',2]])spatialRange(grid,axis.toUpperCase(),axis==='z'?(active===3?.3:-1):-4,axis==='z'?5:4,()=>editTarget().getComponent(index),value=>{const p=editTarget();p.setComponent(index,value);setEditTarget(p);},axis);root.append(grid);if(active!==3&&active!==4){const planes=document.createElement('div');planes.className='switches plane-select';for(const [key,label]of [['view','隨視角拖曳'],['xy','XY 平面'],['xz','XZ 平面'],['yz','YZ 平面']])planes.append(spatialButton(label,()=>{state.dragPlane=key;controls();draw();},state.dragPlane===key));root.append(planes);}}
if(active===5){const grid=document.createElement('div');grid.className='dimension-grid';for(const [key,label]of [['width','寬 X'],['depth','深 Y'],['height','高 Z']])spatialRange(grid,label,.5,5,()=>state[key],value=>state[key]=value,key==='width'?'x':key==='depth'?'y':'z');root.append(grid);}
hint(active===2?'先選一個控制點，再沿三軸改變位置；每個點都能獨立改變。':active===3?'拖動頂部端點或三色箭頭，直接改變擠出方向。':active===4?'選取一張面，再拖曳箭頭自由移動。分離展示後可一鍵回到組合位置。':'拖曳控制點可在所選平面移動；拖曳紅／綠／藍箭頭，分別沿 X／Y／Z 軸移動。');refreshHistoryButtons();}
function setSpatialCopy(){if(galleryMode||active>5)return;const tasks=['沿 X、Y、Z 箭頭移動點，再切換曲線控制點，觀察點如何影響空間中的形狀。','先比較平面與空間曲線。選取任一控制點，沿三軸自由改變位置，再用復原比較。','從波浪面、馬鞍面或平面開始，選取 16 個控制點中的任一點，獨立調整它的 X、Y、Z。','選一個輪廓，拖動擠出端點，改變方向與距離；比較垂直與斜向擠出。','點選各張面，沿三個方向自由移動；最後讓各面回到組合位置，觀察邊界是否相接。','分別調整寬、深、高，觀察三維比例與體積。拿掉頂面，確認封閉狀態如何改變。'];$('task').textContent=tasks[active];if(active===2)$('description').textContent='這張曲面由 4 × 4 控制點共同決定形狀。每個控制點都能在三維空間中獨立移動；不同的排列，可以得到波浪、馬鞍或更自由的曲面。';if(active===3)$('description').textContent='平面輪廓可以沿不同方向直線延伸。改變擠出向量，就會改變傾斜方向與距離。Rhino 的輕量擠出物件限於垂直輪廓平面的情況；斜向擠出通常會建立多重曲面。';}

