function targetToolbarItem(cmd){const loc=toolbarLocations[cmd.name];return (toolbarGroups[loc.group]||[]).find(item=>item.name===cmd.name);}
function commandButtonImage(cmd){return targetToolbarItem(cmd)?.buttonIcon||cmd.icon;}
function makeToolbarPhoto(loc,crop=false,toolRegion=false){const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');let box='0 0 1252 866';if(toolRegion&&!crop)box=loc.kind==='status'?'65 727 1120 86':loc.kind==='open'?'65 55 1120 185':'65 165 1120 345';if(crop){box=loc.kind==='status'?'886 758 278 44':loc.kind==='open'?'507 80 233 46':`70 ${Math.max(232,Math.min(390,loc.y-40))} 128 100`;}svg.setAttribute('viewBox',box);svg.setAttribute('role','img');svg.setAttribute('aria-label',`Rhino 8 Windows 官方介面截圖，標示${loc.area}的${loc.entry}入口`);const photo=document.createElementNS(ns,'image');photo.setAttribute('href',rhinoWindowPhoto);photo.setAttribute('width','1252');photo.setAttribute('height','866');svg.append(photo);let x=loc.x-15,y=loc.y-15,w=30,h=30;if(loc.kind==='status'){x=1020;y=772;w=110;h=25;}if(loc.kind==='open'){x=646;y=87;w=55;h=23;}const mark=document.createElementNS(ns,'rect');for(const [key,value]of Object.entries({x,y,width:w,height:h,rx:3,fill:'#ff9d251c',stroke:'#ff8c28','stroke-width':crop?1.8:4}))mark.setAttribute(key,String(value));svg.append(mark);if(!crop){const isLeft=loc.x<250,cx=isLeft?300:loc.kind==='status'?875:870,cy=loc.kind==='status'?(toolRegion?750:700):Math.max(165,loc.y-50);const leader=document.createElementNS(ns,'path');leader.setAttribute('d',`M ${cx} ${cy} L ${loc.x} ${loc.y}`);leader.setAttribute('stroke','#e77c16');leader.setAttribute('stroke-width','4');leader.setAttribute('fill','none');svg.append(leader);const bg=document.createElementNS(ns,'rect');for(const[key,value]of Object.entries({x:cx-74,y:cy-19,width:148,height:38,rx:6,fill:'#f18a26'}))bg.setAttribute(key,String(value));const label=document.createElementNS(ns,'text');label.setAttribute('x',String(cx));label.setAttribute('y',String(cy+7));label.setAttribute('text-anchor','middle');label.setAttribute('fill','#171a13');label.setAttribute('font-size','20');label.setAttribute('font-family','sans-serif');label.textContent=loc.kind==='flyout'?'先展開這一組':loc.kind==='open'?'先開啟工具列':'找到這個位置';svg.append(bg,label);}return svg;}
function openToolbarPhoto(loc){const dialog=document.createElement('dialog');dialog.className='toolbar-photo-dialog';const head=document.createElement('div');head.className='toolbar-dialog-head';const title=document.createElement('strong');title.textContent='Rhino 8 Windows · '+loc.area;const close=document.createElement('button');close.textContent='關閉 ×';close.onclick=()=>dialog.close();head.append(title,close);dialog.append(head,makeToolbarPhoto(loc));const note=document.createElement('p');note.textContent='官方介面截圖；橘框標示入口。按 Esc 或關閉回到原本的圖示對照。';dialog.append(note);dialog.addEventListener('close',()=>dialog.remove());document.body.append(dialog);dialog.showModal();}
function toolbarSteps(cmd,loc){const group=(loc.groupLabel||'').split('・')[0];const mouse=targetToolbarItem(cmd)?.mouse==='right'?'右鍵':'左鍵';if(loc.kind==='direct')return [`在左側主工具列，找到放大圖中橘框的「${cmd.title}」圖示。`,`按一下左鍵，執行工具。`];if(loc.kind==='flyout')return [`在左側找到「${loc.entry}」圖示。`,`長按左鍵，或點右下黑三角展開工具群。`,`在工具群中，按${mouse}選「${cmd.title}」。`];if(loc.kind==='status')return ['到畫面底部狀態列。','按 Gumball，開啟或關閉操作軸。'];return [`用 Window → Toolbars，開啟 ${group} 工具列。`,cmd.name==='What'?'找到 List 圖示，在這個按鈕上按右鍵，執行 What。':`找到「${cmd.title}」圖示，按一下${mouse}。`];}
function commandControls(){const p=document.createElement('p');p.className='hint';p.textContent='先切回 Standard（標準）分頁，再對照橘框入口。工具列可調寬；長按／黑三角展開，右鍵可能執行另一工具。';$('controls').append(p);}
function drawCommandGuide(){const host=$('command-guide');host.replaceChildren();host.classList.add('command-photo-mode');document.querySelector('.command-location')?.remove();const cmd=commandItems.find(c=>c.name===state.selectedCommand)||commandItems[0],loc=toolbarLocations[cmd.name];const heading=document.createElement('div');heading.className='photo-guide-heading';heading.innerHTML='<div><span class="eyebrow">FIND IT BY ICON</span><h3>在 Rhino 工具列上找到它</h3></div>';const filters=document.createElement('div');filters.className='switches photo-filters';for(const [key,label]of [['all','全部'],['create','建立'],['edit','編輯'],['check','檢查']])filters.append(spatialButton(label,()=>{state.commandCategory=key;if(key!=='all'&&commandItems.find(c=>c.name===state.selectedCommand)?.category!==key)state.selectedCommand=commandItems.find(c=>c.category===key).name;drawCommandGuide();},state.commandCategory===key));heading.append(filters);host.append(heading);const list=document.createElement('div');list.className='command-list icon-picker';for(const item of commandItems.filter(c=>state.commandCategory==='all'||c.category===state.commandCategory)){const b=document.createElement('button');b.className='command-card icon-pick'+(item.name===cmd.name?' selected':'');b.setAttribute('aria-label',`${item.name} ${item.title}`);b.setAttribute('aria-pressed',String(item.name===cmd.name));b.title=item.title+' · '+item.name;const img=document.createElement('img');img.src=commandButtonImage(item);img.alt='';const name=document.createElement('span');name.className='pick-label';name.textContent=commandShortLabels[item.name];b.append(img,name);if(targetToolbarItem(item)?.mouse==='right'){const badge=document.createElement('small');badge.className='mouse-badge';badge.textContent='右鍵';b.append(badge);}b.onclick=()=>{state.selectedCommand=item.name;drawCommandGuide();};list.append(b);}host.append(list);
const figure=document.createElement('figure');figure.className='toolbar-window-photo';figure.append(makeToolbarPhoto(loc,false,!state.toolbarOverview));const photoToolbar=document.createElement('div');photoToolbar.className='photo-toolbar';for(const [overview,label]of [[false,'工具列局部'],[true,'完整介面']]){const b=document.createElement('button');b.className='photo-view-choice';b.textContent=label;b.setAttribute('aria-pressed',String(Boolean(state.toolbarOverview)===overview));b.onclick=()=>{state.toolbarOverview=overview;drawCommandGuide();};photoToolbar.append(b);}const zoomButton=document.createElement('button');zoomButton.className='toolbar-zoom-button';zoomButton.textContent='放大截圖 ⤢';zoomButton.setAttribute('aria-label','放大工具列介面截圖');zoomButton.onclick=()=>openToolbarPhoto(loc);photoToolbar.append(zoomButton);figure.append(photoToolbar);host.append(figure);if(loc.group){const family=document.createElement('div');family.className='toolbar-family';const label=document.createElement('p');label.innerHTML=`展開 <b>${loc.groupLabel}</b> 後，辨認目標圖示`;family.append(label);const icons=document.createElement('div');icons.className='family-icon-index';const seen=new Set();for(const item of toolbarGroups[loc.group]||[]){const realIcon=item.buttonIcon;if(seen.has(realIcon))continue;seen.add(realIcon);const isTarget=realIcon===(targetToolbarItem(cmd)?.buttonIcon||cmd.icon);const member=document.createElement('span');member.className=isTarget?'target-icon':'';member.title=item.name+(item.mouse==='right'?'（右鍵）':'');const img=document.createElement('img');img.src=realIcon;img.alt=item.name;const caption=document.createElement('small');caption.textContent=isTarget&&targetToolbarItem(cmd)?.mouse==='right'?item.name+'／'+cmd.name+'・右鍵':item.name+(item.mouse==='right'?'・右鍵':'');member.append(img,caption);icons.append(member);}family.append(icons);const note=document.createElement('small');note.className='family-note';note.textContent='工具群圖示索引（節錄）；實際行列隨工具列寬度變動。';family.append(note);host.append(family);}const source=document.createElement('p');source.className='toolbar-photo-source';source.textContent='Rhino 8 Windows・Standard 官方介面截圖 · '+(state.toolbarOverview?'完整介面':'工具列局部')+' · 橘框為本課標記';host.append(source);
$('status').textContent=cmd.where;$('headline').replaceChildren();const selectedImage=document.createElement('img');selectedImage.src=commandButtonImage(cmd);selectedImage.alt='';const text=document.createElement('span');const title=document.createElement('strong');title.textContent=cmd.title;const english=document.createElement('small');english.textContent=cmd.name;text.append(title,english);$('headline').append(selectedImage,text);$('description').textContent=cmd.description;const steps=toolbarSteps(cmd,loc);$('task').replaceChildren();const stepList=document.createElement('span');stepList.className='toolbar-steps';stepList.setAttribute('role','list');for(const step of steps){const li=document.createElement('span');li.setAttribute('role','listitem');li.textContent=step;stepList.append(li);}$('task').append(stepList);const zoom=document.createElement('section');zoom.className='command-location toolbar-location';const zoomTitle=document.createElement('p');zoomTitle.className='eyebrow';zoomTitle.textContent=loc.kind==='flyout'?'先找到這個入口・實際畫面放大':loc.kind==='open'?'工具列未顯示時，從這裡開啟':'實際畫面放大・對照周圍圖示';zoom.append(zoomTitle,makeToolbarPhoto(loc,true));$('task').after(zoom);$('takeaway').textContent=cmd.name==='What'?'同一個 List 按鈕：左鍵是 List，右鍵才是 What。':loc.kind==='flyout'?'先長按或點黑三角展開，再對目標按鈕按左鍵；長按和右鍵是不同操作。':loc.kind==='status'?'這個入口在底部狀態列，不是左側工具列。':'把游標停在按鈕上，可核對提示中的名稱與左右鍵功能。';$('commands').replaceChildren(document.createTextNode(cmd.tip));const fallback=document.createElement('span');fallback.className='menu-fallback';fallback.textContent='另一種入口（選單）：'+cmd.path.join(' → ');$('commands').append(fallback);const link=document.createElement('a');link.href=cmd.url;link.target='_blank';link.rel='noopener';link.textContent='官方工具說明 ↗';$('commands').append(link);const demo=document.createElement('span');demo.className='flyout-demo';demo.textContent='工具群展開示範（以矩形為例）';const demoImage=document.createElement('img');demoImage.src=rhinoFlyoutDemo;demoImage.alt='官方示範：長按或點右下黑三角，展開矩形工具群';demo.append(demoImage);$('commands').append(demo);$('rhino-details').open=false;}


