window.lessonSnapshot=()=>({active,state:JSON.parse(JSON.stringify(state)),status:$('status').textContent,objects:group.children.length,axes:axisHandles.filter(h=>h.isMesh).map(h=>{const p=h.getWorldPosition(v(0,0,0)).project(camera),r=renderer.domElement.getBoundingClientRect();return {axis:h.userData.axis,x:r.left+(p.x+1)*r.width/2,y:r.top+(1-p.y)*r.height/2};}),handles:handles.map(h=>{const p=h.position.clone().project(camera),r=renderer.domElement.getBoundingClientRect();return {x:r.left+(p.x+1)*r.width/2,y:r.top+(1-p.y)*r.height/2};})});
